\begin{abstract}
Video summarization creates an abridged version (i.e., a summary) that provides a quick overview of the video while retaining pertinent information. 
In this work, we focus on summarizing instructional videos and propose a method for breaking down a video into meaningful segments, each corresponding to essential steps in the video. 
We propose \textbf{HierSum}, a hierarchical approach that integrates fine-grained local cues from subtitles with global contextual information provided by video-level instructions. 
Our approach utilizes the ``most replayed" statistic as a supervisory signal to identify critical segments, thereby improving the effectiveness of the summary. 
We evaluate on benchmark datasets such as TVSum, BLiSS, Mr.HiSum, and the WikiHow test set, and show that HierSum consistently outperforms existing methods in key metrics such as F1-score and rank correlation. 
We also curate a new multi-modal dataset using WikiHow and EHow videos and associated articles containing step-by-step instructions. 
Through extensive ablation studies, we demonstrate that training on this dataset significantly enhances summarization on the target datasets. 
The code and dataset will be released upon acceptance.
\end{abstract}    
\section{Introduction}
\label{sec:intro}

\paragraph{Loss Function:} The final loss  comprises: \textit{(i)} Classification loss; and \textit{(ii)} Contrastive loss. \\
\noindent\emph{(i) Classification Loss}. We apply focal loss~\cite{lin2017focal} to classify the importance score.

\small{
\begin{equation}
% \begin{aligned}
    L_\text{cls}=
    \frac{1}{N}\sum_{i=1}^{N}\left\{
    \begin{matrix}
         -\alpha(1-p_i)^\gamma \log(p_i), & \mbox{if} & y_i=1 \\
         -(1-\alpha)p_i^\gamma \log(1-p_i), & \mbox{if} & y_i=0
    \end{matrix}\right. 
    % L_{cls} = L_{video} + L_{text}
% \end{aligned} 
\end{equation}
}
\normalsize {
\begin{equation}
L_\text{cls} = L_{\text{cls}_\text{video}} + L_{\text{cls}_\text{text}}
\end{equation}
}

where $p_i$ is the predicted score for each frame and sentence, and $y_i$ is the ground-truth label where $y_i=1$ indicating \textit{i$^{th}$} frame as the keyframe/key-sentence. 
During the global step, only $L_{\text{cls}_\text{video}}$ is used to train. 
% \ninja{check this, some of these terms are not defined}

While the focal loss is applied for the importance labels, as we also utilize the most-replayed statistics during training, we employ a mean-squared error loss on the relevancy scores. 
All frames with relevancy scores $\ge$ 0.15 are considered ``important" and labeled as 1.
$$\mathcal{L}_{mse} = \frac{1}{N}\sum_{i=1}^{N} ||s_i - p_i||^2$$
where $s_i$ is the ground-truth relevancy score.

\noindent\textbf{Contrastive Losses}: Following A2Summ~\cite{he2023align} and driven by the success of contrastive learning~\cite{radford2021learning,beedu2025text,choi2023multimodal,haresamudram2025limitations}, we design an auxiliary contrastive loss, $\mathcal{L}_\text{inter}$, by maximizing the cosine similarity of the video embedding [CLSV] and text embedding [CLST] from $B$ positive pairs from the batch, and $B^2 - B$ negative samples.
While prior methods employ inter-modality contrastive loss, A2Summ~\cite{he2023align} proposes an intra-modality loss for video summarization task that is able to distinguish keyframes and sentences from the background frames and less-related sentences.

To achieve this, the wrongly classified frame/sentence with high prediction scores are selected as hard-negative samples, after excluding the samples that are close to positive keyframe samples to avoid confusing the model, and the pre-defined ground-truth samples are considered as positive samples. 
For more information on intra-sample contrastive loss, we refer readers to~\cite{he2023align}.
The loss is defined as:
\begin{equation}
\begin{aligned}
    \mathcal{L}_\text{intra} = \mathbb{E}_{z \sim \mathcal{I}_{PF}, z+\sim \mathcal{I}_{PS}, z-\sim \mathcal{I}_{HNF}}l(z,z^+,z^-) \\
    + \mathbb{E}_{z \sim \mathcal{I}_{PS}, z+\sim \mathcal{I}_{PF}, z-\sim \mathcal{I}_{HNS}}l(z,z^+,z^-)
\end{aligned}
\end{equation}
Where $\mathcal{I}_{PF}, \mathcal{I}_{PS}, \mathcal{I}_{HNF}, \mathcal{I}_{HNS}$ are positive frames, positive sentences, hard-negative frames and hard-negative sentences.
% \irfan{this equation does not look right!}

The final loss is defined as:
\begin{equation}
    \mathcal{L} = \mathcal{L}_\text{cls} + \alpha \mathcal{L}_\text{mse} + \beta \mathcal{L}_\text{inter} + \lambda \mathcal{L}_\text{intra}
\end{equation}
where $\alpha$, $\beta$ and $\gamma$ are hyper-parameters controlling the trade off between the losses.
\section{Experiments}
\label{sec:exp}
\subsection{Datasets}
We evaluate our approach on four datasets, namely: TVSum~\cite{song2015tvsum}, BLiSS~\cite{he2023align}, Mr.HiSum~\cite{sul2024mr}, and WikiHow~\cite{narasimhan2022tl}. \\

\noindent \textbf{TVSum} contains 50 videos spanning 10 categories (how-to videos, news, documentaries, etc.) with five videos per category.
Each video is typically 2-10 minutes long and annotated by 20 people. 
Video summaries are constructed for each user annotation using the 0/1 knapsack algorithm.

